"""Handwritten queue, stack, heap, and linked-list reference contracts."""


def section(title, *paragraphs, rows=None, columns=None):
    result = {"title": title, "paragraphs": list(paragraphs)}
    if rows is not None:
        result["table"] = {"columns": columns or ["Member", "Description"], "rows": rows}
    return result


def member_types(category, memory="heap", immutable=False, synonyms=True, iterators=False,
                 const_only=False, size_type=False, tags=True):
    rows = []
    if tags:
        rows.extend([
            ["`category_type`", f"`{category}_tag`; identifies the container family."],
            ["`mutability_type`", "`immutable_tag`." if immutable else "`mutable_tag`."],
            ["`memory_type`", f"`{memory}_tag`; the declared storage tag."],
        ])
    rows.append(["`value_type`", "The element type `T` (spelled `t` in some declarations)."])
    if size_type:
        rows.append(["`size_type`", "`usize`; the unsigned count/index type."])
    rows.extend([
        ["`reference`, `ref`" if synonyms else "`reference`", "`const T&`." if const_only else "`T&`."],
        ["`const_reference`, `const_ref`" if synonyms else "`const_reference`", "`const T&`."],
        ["`pointer`", "`const T*`." if const_only else "`T*`."],
        ["`const_pointer`", "`const T*`."],
    ])
    if iterators:
        rows.extend([
            ["`iterator`", "`const T*`." if const_only else "`T*`."],
            ["`const_iterator`", "`const T*`."],
        ])
    return section("Member types", rows=rows)


def typename(name, header, summary, sections, covers=()):
    item = {"name": name, "header": header, "summary": summary, "sections": sections}
    if covers:
        item["covers"] = list(covers)
    return item


